using Microsoft.ML.Data;

namespace ChurnPredictor.Models;

/// <summary>
/// Raw CSV row with Churned as string for initial loading.
/// </summary>
public class ChurnInputRaw
{
    [LoadColumn(0)]
    public float Age { get; set; }

    [LoadColumn(1)]
    public float Income { get; set; }

    [LoadColumn(2)]
    public string Region { get; set; } = string.Empty;

    [LoadColumn(3)]
    public float PurchaseHistory { get; set; }

    [LoadColumn(4)]
    public string Churned { get; set; } = string.Empty;
}

/// <summary>
/// Model input after Yes/No is mapped to bool Label.
/// </summary>
public class ChurnInput
{
    public float Age { get; set; }
    public float Income { get; set; }
    public string Region { get; set; } = string.Empty;
    public float PurchaseHistory { get; set; }

    [ColumnName("Label")]
    public bool Churned { get; set; }
}

public class ChurnPrediction
{
    [ColumnName("PredictedLabel")]
    public bool PredictedLabel { get; set; }

    public float Probability { get; set; }

    public float Score { get; set; }
}

using ChurnPredictor.Models;
using Microsoft.ML;

namespace ChurnPredictor.Services;

public class ChurnModelService
{
    private readonly MLContext _mlContext;
    private readonly ILogger<ChurnModelService> _logger;
    private readonly string _csvPath;
    private readonly string _modelPath;

    public ChurnModelService(ILogger<ChurnModelService> logger, IWebHostEnvironment env)
    {
        _mlContext = new MLContext(seed: 42);
        _logger = logger;
        _csvPath = Path.Combine(env.ContentRootPath, "Data", "customers.csv");
        _modelPath = Path.Combine(env.ContentRootPath, "Data", "churn_model.zip");
    }

    public string ModelPath => _modelPath;

    public void TrainAndSave()
    {
        _logger.LogInformation("Loading data from {Path}", _csvPath);

        var rawData = _mlContext.Data.LoadFromTextFile<ChurnInputRaw>(
            _csvPath, hasHeader: true, separatorChar: ',');

        // Map "Yes"/"No" string to bool Label
        var mappedData = _mlContext.Data.CreateEnumerable<ChurnInputRaw>(rawData, reuseRowObject: false)
            .Select(row => new ChurnInput
            {
                Age = row.Age,
                Income = row.Income,
                Region = row.Region,
                PurchaseHistory = row.PurchaseHistory,
                Churned = string.Equals(row.Churned, "Yes", StringComparison.OrdinalIgnoreCase)
            })
            .ToList();

        var data = _mlContext.Data.LoadFromEnumerable(mappedData);

        var split = _mlContext.Data.TrainTestSplit(data, testFraction: 0.2, seed: 42);

        var pipeline = _mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", nameof(ChurnInput.Region))
            .Append(_mlContext.Transforms.Concatenate("Features",
                nameof(ChurnInput.Age),
                nameof(ChurnInput.Income),
                nameof(ChurnInput.PurchaseHistory),
                "RegionEncoded"))
            .Append(_mlContext.BinaryClassification.Trainers.SdcaLogisticRegression(
                labelColumnName: "Label", featureColumnName: "Features"));

        _logger.LogInformation("Training model...");
        var model = pipeline.Fit(split.TrainSet);

        var predictions = model.Transform(split.TestSet);
        var metrics = _mlContext.BinaryClassification.Evaluate(predictions, labelColumnName: "Label");

        _logger.LogInformation("Model metrics — AUC: {Auc:F4}, F1: {F1:F4}, Accuracy: {Acc:F4}",
            metrics.AreaUnderRocCurve, metrics.F1Score, metrics.Accuracy);

        _mlContext.Model.Save(model, data.Schema, _modelPath);
        _logger.LogInformation("Model saved to {Path}", _modelPath);
    }

    public bool ModelExists() => File.Exists(_modelPath);
}

namespace ChurnPredictor.Services;

/// <summary>
/// Trains the churn model on startup if no saved model exists.
/// </summary>
public class ChurnModelTrainer : IHostedService
{
    private readonly ChurnModelService _modelService;
    private readonly ILogger<ChurnModelTrainer> _logger;

    public ChurnModelTrainer(ChurnModelService modelService, ILogger<ChurnModelTrainer> logger)
    {
        _modelService = modelService;
        _logger = logger;
    }

    public Task StartAsync(CancellationToken cancellationToken)
    {
        if (_modelService.ModelExists())
        {
            _logger.LogInformation("Saved model found — skipping training.");
        }
        else
        {
            _logger.LogInformation("No saved model found — training now.");
            _modelService.TrainAndSave();
        }

        return Task.CompletedTask;
    }

    public Task StopAsync(CancellationToken cancellationToken) => Task.CompletedTask;
}

