using ChurnPredictor.Models;
using ChurnPredictor.Services;
using Microsoft.Extensions.ML;

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddSingleton<ChurnModelService>();
builder.Services.AddHostedService<ChurnModelTrainer>();

builder.Services.AddPredictionEnginePool<ChurnInput, ChurnPrediction>()
    .FromFile(modelName: "ChurnModel",
        filePath: Path.Combine(builder.Environment.ContentRootPath, "Data", "churn_model.zip"),
        watchForChanges: true);

var app = builder.Build();

app.MapGet("/", () => "Hello");

app.MapPost("/predict", (PredictionEnginePool<ChurnInput, ChurnPrediction> pool, ChurnRequest request) =>
{
    var input = new ChurnInput
    {
        Age = request.Age,
        Income = request.Income,
        Region = request.Region,
        PurchaseHistory = request.PurchaseHistory
    };

    var prediction = pool.Predict(modelName: "ChurnModel", example: input);

    return Results.Ok(new { willChurn = prediction.PredictedLabel, probability = prediction.Probability });
});

app.MapPost("/train", (ChurnModelService modelService) =>
{
    modelService.TrainAndSave();
    return Results.Ok(new { message = "Model retrained successfully." });
});

app.Run();

record ChurnRequest(float Age, float Income, string Region, float PurchaseHistory);

